const report = $input.first().json;
const jobs = report.open_jobs || [];
const lines = [`Recruitment digest (${new Date(report.generated_at).toDateString()})`, ''];

if (!jobs.length) lines.push('No open vacancies.');
for (const j of jobs) {
  lines.push(`${j.title}`);
  lines.push(`  ${j.total_applications} applications (${j.new_last_24h} new in last 24h), ${j.awaiting_review} awaiting review`);
  if (j.top_candidates.length) {
    lines.push('  Top candidates:');
    j.top_candidates.forEach((c, i) => lines.push(`    ${i + 1}. ${c.name}: ${c.score}/100 [${c.status}]${c.must_have_met ? '' : ' (must-have gap)'}`));
  }
  lines.push('');
}
lines.push('Scores are advisory; decisions are made by recruiters.');

const awaiting = jobs.reduce((n, j) => n + j.awaiting_review, 0);
return [{ json: { subject: `Recruitment digest: ${awaiting} candidate(s) awaiting review`, text: lines.join('\n'), to: $env.RECRUITER_EMAIL } }];
